    static_assert(LEN_ARRAY(pmd_animation_table) == PMD_ANIM_COUNT);

    config_custom_animation_entry_t get_config_animation_name_pmd(size_t index) {
        assert(index < PMD_ANIM_COUNT);
        const auto& entry = pmd_animation_table[index];
        return { PMD_STRINGS + entry.name, PMD_STRINGS + entry.id, PMD_STRINGS + entry.fqid, PMD_STRINGS + entry.fqname, entry.anim_index, entry.set, entry.layout };
    }

    int config_parse_animation_name_pmd(config::config_t& config, const char *value) {
        int ret = -1;
        for (size_t i = 0;ret < 0 && i < PMD_ANIM_COUNT;++i) {
            const auto& entry = pmd_animation_table[i];
            if (strcmp(value, PMD_STRINGS + entry.name) == 0 ||
                strcmp(value, PMD_STRINGS + entry.id) == 0 ||
                strcmp(value, PMD_STRINGS + entry.fqid) == 0 ||
                strcmp(value, PMD_STRINGS + entry.fqname) == 0) {
                config.animation_index = entry.anim_index;
                config.animation_custom_set = entry.set;
                config.animation_sprite_sheet_layout = entry.layout;
                ret = entry.anim_index;
                break;
            }
        }
        return ret;
    }
